        var ts = theilSen(x, y, S.trendMax);
        if (!isNum(ts.a)) ts = { a: y.length ? y[y.length - 1] : NaN, b: 0 };
        var res = [], sx = 0;
        for (var k = 0; k < x.length; k++) { res.push(y[k] - ts.a - ts.b * x[k]); sx += x[k]; }
