        ev.dtc_s = dtc / SEC;
        ev.pwf0 = pwf0;
        ev.pwf0SE = isNum(se) ? se : tr.sigmaRes;
        ev.trend = trendRebase(tr, tc);
        ev.ramp = ramp;
        if (isNum(ev.tEnd_ms)) ev.dtEnd_h = mMax(0, (ev.tEnd_ms - tc) / HOUR);
