        for (var x = t2; x < ts2 - 1e-12; x += dth) t.push(x);
        var d = dth, f = Math.pow(10, 1 / 100) - 1;
        while (ts2 + d < tEnd) { t.push(ts2 + d); d += Math.max(dth, d * f); }
        t.push(tEnd);
