        var lines = [cols.map(function (c) { return c[1]; }).join(',')];
        for (var i = 0; i < ds.t.length; i++) lines.push(cols.map(function (c) { var v = ds[c[0]][i]; return fin(v) ? String(v) : ''; }).join(','));
