        var Gt = votes.length ? median(votes.map(function (p) { return p.G; })) : NaN;
        if (fin(Gt)) { var bd = Infinity; for (i = 0; i < n; i++) if (fin(d.G[i]) && Math.abs(d.G[i] - Gt) < bd) { bd = Math.abs(d.G[i] - Gt); ref = i; } }
        var lo, hi;
