            while (b < n - 1 && lx[b + 1] - lx[i] <= hw) b++;
            while (b - a + 1 < 5 && (a > 0 || b < n - 1)) { if (a > 0) a--; if (b < n - 1 && b - a + 1 < 5) b++; }
