        var gasT = _isGasType(t), oil = t === 'oil', water = t === 'water' || t === 'waterinj';
        var cgr = _fin(s.cgr) ? s.cgr : 0, wgr = _fin(s.wgr) ? s.wgr : 0, L0 = _lib();
