                grid: { x: xs.slice(), y: ys.slice(), q: q, stable: stab, labelsX: xs.map(function (x) { return typeof raw1[x] === 'string' ? raw1[x] : null; }), labelsY: ys.map(function (y) { return typeof raw2[y] === 'string' ? raw2[y] : null; }) },
