            L.push([''].concat(res.grid.x.map(function (x, i) { return res.grid.labelsX[i] || x; })).map(_cell).join(','));
            res.grid.y.forEach(function (y, j) { L.push([res.grid.labelsY[j] || y].concat(res.grid.q[j]).map(_cell).join(',')); });
