    NS._drCharts = { F: _drF, L: _drL, f2: _drF2, table: { NL: DR_NLX.slice(), F: JSON.parse(JSON.stringify(DR_CH)), Nd: DR_NDX.slice(), L1: DR_L1.slice(), L2: DR_L2.slice(), f2x: DR_F2X.slice(), f2y: DR_F2Y.slice() } };
